                                    /** @description Secret-named values and credentials removed. */
                                    secret: number;
                                    /** @description Token-shaped strings removed (pat_, sk-, JWT-like, bearer). */
                                    token: number;
                                    /** @description URLs reduced to scheme://<host>/… (path, query and userinfo dropped). */
                                    url: number;
                                    /** @description Hostnames replaced by <host>. */
                                    host: number;
                                    /** @description IP addresses replaced by <ip>. */
                                    ip: number;
                                    /** @description Email addresses replaced by <email>. */
                                    email: number;
                                    /** @description Filesystem paths replaced by <path> or <library>. */
                                    path: number;
                                    /** @description Media or subtitle file names replaced by <file>. */
